namespace Lifestone.Client.Options;

public static partial class OptionCatalog
{
    /// <summary>
    /// The headless host's own options (M2 state track; parsed by src/Lifestone.Headless/HeadlessOptions.cs). The headless
    /// host also reads the Core options marked <see cref="OptionScenes.Headless"/> and the <see cref="Session"/> group.
    /// </summary>
    public static OptionGroup Headless() => new("Headless host", "dotnet Lifestone.Headless.dll",
    [
        new("--scenario", "login|holtburg-laps|academy-exit|mage-build|fighter-build|gear|buff|fight|death-and-regear|hunt|wayfind", "What the run does (default login: log in, enter the world, check the server mod's status, log off and quit). holtburg-laps walks laps around the Holtburg lifestone and academy-exit walks out of the Training Academy, both with zero server corrections required. mage-build finds or creates the test account's level-126 combat mage (the character name is fixed; --character and --create-character are ignored with a warning, and any --account but the default test account is refused), spends its experience and credits on the template, learns the arena profile's spells, then logs off; it is idempotent (a ready mage is only verified) and logs '[mage] verdict mage=<ready|built|failed> level=<n> template=<ok|short> spells=<n>/<m> built_steps=<n>'. fighter-build (M4 1.1) finds or creates the test account's level-40 fighter 'Holtburg Hunter' (the name is fixed; the same account rules as mage-build), spends its experience and credits on the fighter template, has the server mod grant its kit, wields the Mace, wears the five leather pieces, places it in Holtburg and logs off; idempotent (a ready fighter is only verified) and logs '[fighter] verdict fighter=<ready|built|failed> level=<n> template=<ok|short> kit=<ok|missing> wielded=<wcid|0> worn=<n>'. gear enters that mage (run mage-build first; the same character and account rules), has the server mod grant its kit (a wand, a leather set and the spell components of the arena profile, as the account casts them; a top-up), wields the wand and wears the five armour pieces, then logs off; it is idempotent (a ready mage sends no gear step: gear_steps counts the wand, the armour and the wields, topup counts the component requests, and the cast, when it is on, still burns components and mana) and logs '[gear] verdict gear=<wielded|failed> worn=<n> kit=<held>/<lines> gear_steps=<n> topup=<n> cast=<ok|fizzled|failed|n/a>' (cast is report-only: after the gear it enters the magic combat mode, casts one Creature Enchantment self buff, waits for the mana it needs and returns to non-combat). buff is the gear scenario without its cast, then the magic combat mode, the buff cycle of the profile's 24 lines (the --buff-* options; a regeneration wait is spent in non-combat), a forced re-buff pass that recasts the line closest to expiry while it is still active, non-combat and the log off (the same character and account rules; idempotent: a second run casts no self line) and logs '[buff] verdict gear=<wielded|failed> worn=<n> buffs=<active>/<wanted> levels=<line:level,..> rebuffed=<yes|no> forced=<yes|no> min_remaining_s=<s> transfers=<fired>/<tried> revitalizes=<n> fizzles=<n> mana_min=<n> cycle_s=<s> misses=<names|none>' (its default time limit is 3000 s). fight is the gear scenario, a buff top-up (the buff cycle runs only when a profile line is missing or has under 600 s left), the teleport to the Aluvian Black Spawn Den, the magic combat mode and a Flame Bolt fight against the Tusker Slaves of the arrival's floor until --fight-kills kills (default 1) or --fight-seconds (default 300), walking the floor when nothing is in range or three casts miss, then non-combat and the log off (the same character and account rules); it logs '[fight] verdict gear=<wielded|failed> worn=<n> buffs=<skipped|topped-up:<n>> kills=<n> damage_dealt=<n> spells_cast=<n> misses=<n> xp_gained=<n> damage_taken=<n> hits_taken=<n> evades=<n> level=<I-VII> range_m=<m> projectiles=<n> walks=<n> fight_s=<s>' (its default time limit is 3600 s). death-and-regear (M3 3.2) is the gear scenario, then the mage's spell bars (bar 1 the arena profile's lines, bar 2 Flame Bolt I to VII; only the spells a bar lacks are sent), a bind at Holtburg's lifestone (the Holtburg point of interest, the nearest lifestone object, a Use on it), the teleport to the Aluvian Black Spawn Den, a suicide there when any enchantment but the vitae is active (a death removes every enchantment, so the mage meets the tuskers unbuffed), a walk to the nearest tusker cell and non-combat among the Tusker Slaves until they kill the mage (--death-seconds, default 600), the respawn at the lifestone, the gear scenario again (what the death dropped is spawned again, the wand and the five pieces wielded) and the log off (the same character and account rules); it changes the character (vitae, dropped items, a corpse in the den) and logs 'death ok=<true|false> died=<n> suicides=<n> vitae=<pct> respawn=<lifestone|elsewhere|none> corpse=<n> purged=<n> protected=<n> vitals_pct=<x|n/a> gear_restored=<yes|no> worn=<n> hits_taken=<n> damage_taken=<n> evades=<n> health_min_pct=<x|n/a> death_s=<s|n/a> death_frame_max_ms=n/a fight_frame_max_ms=n/a deaths=<n> corpses_stale=<n> protection=<dispelled|expired|none> vitae_paid=<xp|n/a> vitae_after=<pct|n/a> bars=<set:n|ok|n/a> unbuff=<suicide|none|n/a> bound=<yes|no>' (its default time limit is 900 s plus --death-seconds). hunt (M4 1.2) enters the test account's level-40 fighter 'Holtburg Hunter' only (the same account rules as fighter-build), binds it at Holtburg's lifestone, uses a Potion of Healing (at most 2) when its health is under 60%, teleports it to the first dry cell of the Low B belt (the level 8 to 20 ground south-west of the town), picks the nearest creature of the belt's names and fights it with --hunt-weapon until --hunt-kills kills (default 1) or --hunt-seconds (default 300), then sets non-combat, restores the Mace, teleports back to Holtburg and logs off; a health fall under 30% cancels the attack and returns (the run fails with returned=yes); it logs 'hunt fighter=<ok|wrong> kills=<n> swings=<n> shots=<n> hits=<n> misses=<n> damage_dealt=<n> damage_taken=<n> hits_taken=<n> evades=<n> xp_gained=<n> returned=<yes|no>' (all report-only), and changes the character (experience, vitae, healing potions) its default time limit is 600 s plus --hunt-seconds. wayfind (P5a S6) logs in as the fighter of --account (test-melee: Holtburg Brawler, test-archer: Holtburg Archer, test: Holtburg Hunter), optionally places it at --from, runs to --to with the wayfinder and the human keys through the headless streamer, with --wayfind-back runs back, prints the wayfind lines (see --to) and logs off; its default time limit is the straight-line route at 4.8 m/s plus 300 s per leg."),
        new("--fighter", "hunter|melee|archer", "Which fighter template --scenario=fighter-build builds and --scenario=hunt hunts with (M4 P4): hunter is Holtburg Hunter on account test (the Mace and the Shortbow), melee is Holtburg Brawler on test-melee (Heavy Weapons, the Mace, no bow) and archer is Holtburg Archer on test-archer (Missile Weapons, the Shortbow and 500 Arrows, no Mace). The default follows --account (test = hunter, test-melee = melee, test-archer = archer); a value that does not match --account fails the run."),
        new("--fighter-recreate", "on|off", "Opt-in for --scenario=fighter-build on test-melee or test-archer only (the Brawler and the Archer; refused for the Hunter, on any other account and for any other scenario; M4 P5a C5, owner decision D40): when the existing fighter was created with attribute values other than its template's (the build otherwise fails with template=mismatch:<attribute> <have>/<want> before it buys anything), the build logs off, deletes that character through the client's retail character delete (the character stays pending deletion, restorable in ACE's window; ACE frees the name at once), waits for the server to list it as pending deletion, creates the template's character through the normal creation and builds it to the target; it logs 'recreated=yes old=pending-deletion' in the verdict. With no mismatch it does nothing extra. It never uses the server mod's purge. Default off.", ValueOptional: true),
        new("--laps", "N", "Laps of the Holtburg route for --scenario=holtburg-laps (default 3)."),
        new("--create-character", "NAME", "Use this character, creating it first on the account when it does not exist."),
        new("--summary", "PATH", "Also write the run's summary as JSON to PATH (relative to the repository root, never under src/ or tests/); it holds no secrets."),
    ], OptionScenes.Headless);
}
